protected static function addMissingParts(string $source, string $target): string
{
    $pattern = '/'.preg_replace('/\d+/', '[0-9]+', preg_quote($target, '/')).'$/';

    $result = preg_replace($pattern, $target, $source, 1, $count);

    return $count ? $result : $target;
}

